insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('AL', 'AL-P-20', 'TVSH 20% — blerje brenda vendit', '{"en":"VAT 20% — domestic purchase"}'::jsonb, null, 'percent', 20, 'purchase', 'domestic', date '2015-01-01', null, 'Ligji Nr. 92/2014, neni 48 dhe neni 68 — e drejta e zbritjes së TVSH-së mbi blerjet e përdorura për qëllime të veprimtarisë ekonomike të tatueshme; neni 75, shkronja «a» — kriteri i zotërimit të një fature të lëshuar sipas neneve 96-105.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ligji-92-2014', null, null, null, null),
  ('AL', 'AL-P-IMPORT-20', 'TVSH 20% — import mallrash', '{"en":"VAT 20% — import of goods"}'::jsonb, null, 'percent', 20, 'purchase', 'import', date '2015-01-01', null, 'Ligji Nr. 92/2014, neni 50 — shkalla e TVSH-së në importim është ajo e zbatueshme për shitjen e të njëjtit mall brenda territorit; neni 34 — lindja e tatimit dhe kërkueshmëria ndodhin kur importimi kryhet; neni 75, shkronja «c» — e drejta e zbritjes kërkon dokumentin doganor të çlirimit për qarkullim të lirë, ku shënohet shuma e TVSH-së së paguar.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ligji-92-2014', null, null, null, null),
  ('AL', 'AL-P-REVCHG-20', 'TVSH 20% — vetëngarkim mbi shërbime të marra nga jashtë', '{"en":"VAT 20% — self-assessment on services received from abroad"}'::jsonb, null, 'percent', 20, 'purchase', 'foreign_services_received', date '2015-01-01', null, 'Ligji Nr. 92/2014, neni 86, pika 2 — TVSH-ja paguhet nga personi i tatueshëm marrës i shërbimeve të përcaktuara në nenin 24, pika 1 (rregulli i përgjithshëm i vendit të furnizimit të shërbimeve mes personave të tatueshëm), kur furnizuesi nuk është i vendosur në Republikën e Shqipërisë; neni 75, shkronja «ç» — e drejta e zbritjes kërkon formalitetet e përcaktuara me udhëzim të Ministrit të Financave. Shqipëria është jashtë sistemit të përbashkët të TVSH-së; ky mekanizëm i vetëngarkimit korrespondon me kategorinë ''foreign_services_received'' të docs/packs.md dhe jo me një ''reverse charge'' brenda BE-së.', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ligji-92-2014', null, null, null, null),
  ('AL', 'AL-S-20', 'TVSH 20% — shitje me shkallë standarde', '{"en":"VAT 20% — standard-rated sale"}'::jsonb, null, 'percent', 20, 'sale', 'domestic', date '2015-01-01', null, 'Ligji Nr. 92/2014, neni 48 — shkalla standarde e TVSH-së për furnizimet e mallrave dhe shërbimeve, e aplikuar si përqindje e vlerës së tatueshme, është 20%; neni 32 — lindja dhe kërkueshmëria e tatimit ndodhin kur furnizimi kryhet.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ligji-92-2014', null, null, null, null),
  ('AL', 'AL-S-6-ACCOM', 'TVSH 6% — shërbimi i akomodimit dhe i strukturave akomoduese', '{"en":"VAT 6% — accommodation service"}'::jsonb, null, 'percent', 6, 'sale', 'domestic', date '2017-06-05', null, 'Ligji Nr. 92/2014, neni 49, pika 3, shtuar me Ligjin Nr. 71/2017 — shkalla e reduktuar 6% zbatohet për furnizimin e shërbimit të akomodimit në strukturat akomoduese; Buletini Fiskal 2024 (Ministria e Financave), pika II.1.1, konfirmon normën 6% për akomodimin ende në fuqi për vitin 2024, si dhe shtrirjen e saj te shërbimet e strukturave ''Hotel/Resort me pesë yje, status special'' me markë tregtare të njohur ndërkombëtarisht dhe te akomodimi/restoranti (pa pije) i agroturizmit të certifikuar.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ligji-92-2014', null, null, null, null),
  ('AL', 'AL-S-6-BOOKS', 'TVSH 6% — furnizimi i librave të çdo lloji', '{"en":"VAT 6% — supply of books"}'::jsonb, null, 'percent', 6, 'sale', 'domestic', date '2021-01-01', null, 'Buletini Fiskal 2024 (Ministria e Financave), pika II.1.1 — shkalla e reduktuar 6% zbatohet për furnizimin e librave të çdo lloji. Ligji Nr. 92/2014, neni 53, shkronja «j», në tekstin origjinal të vitit 2014, e trajtonte furnizimin e librave si të përjashtuar nga TVSH-ja; kërkimi për këtë paketim nuk ka mundur të gjejë numrin e saktë të ligjit ndryshues që e ka kaluar librin nga furnizim i përjashtuar në furnizim me shkallë të reduktuar 6% — data e mësipërme (2021-01-01) është një supozim i arsyeshëm bazuar në kohën kur norma 6% e librave shfaqet në praktikën e administratës, dhe duhet verifikuar me një kontabilist vendas, siç shënohet në README.md.', 'S', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'buletini-fiskal-2024', null, null, null, null),
  ('AL', 'AL-S-EXEMPT-FIN', 'Përjashtuar nga TVSH — shërbime financiare dhe sigurimi', '{"en":"VAT exempt — financial and insurance services"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2015-01-01', null, 'Ligji Nr. 92/2014, neni 53, shkronjat «a»-«d» — janë furnizime të përjashtuara nga TVSH-ja shërbimet e sigurimit dhe risigurimit, dhënia dhe negocimi i kredive, garancitë e kredive, dhe transaksionet mbi llogaritë, depozitat, valutën dhe letrat me vlerë.', 'E', null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ligji-92-2014', null, null, null, null),
  ('AL', 'AL-S-EXEMPT-RENT', 'Përjashtuar nga TVSH — dhënie me qira e pasurisë së paluajtshme', '{"en":"VAT exempt — rental of immovable property"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2015-01-01', null, 'Ligji Nr. 92/2014, neni 53, shkronja «h» — dhënia me qira e pasurive të paluajtshme është e përjashtuar nga TVSH-ja, me përjashtimet e numëruara në nën-shkronjat (i)-(v) të së njëjtës shkronjë (qira deri në dy muaj, strehim hotelier, parkim, pajisje të fiksuara, kasaforta), të cilat mbeten të tatueshme dhe nuk përdorin këtë kod.', 'E', null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ligji-92-2014', null, null, null, null),
  ('AL', 'AL-S-EXPORT', 'TVSH 0% — eksport mallrash', '{"en":"VAT 0% — export of goods"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2015-01-01', null, 'Ligji Nr. 92/2014, neni 57 (KREU VIII, furnizimet me shkallë zero) — trajtohet me shkallë zero për qind furnizimi i mallrave të eksportuara jashtë territorit doganor të Republikës së Shqipërisë. Shqipëria është jashtë sistemit të përbashkët të TVSH-së të Bashkimit Evropian (Direktiva 2006/112/KE, neni 5(2)); asnjë kod VATEX dhe asnjë nga trajtimet ''intracom_*'' nuk zbatohen këtu, siç shënohet për vendet jashtë BE-së në docs/packs.md.', 'G', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ligji-92-2014', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
