insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('AL', 'AL-TVSH-FDP', 'Deklarata e TVSH-së — Formulari i Deklarimit dhe Pagesës (FDP)', array['month']::declaration_period[], 'month'::declaration_period, date '2015-01-01', null, 'Ligji Nr. 92/2014, neni 106 — çdo person i tatueshëm duhet të dorëzojë një deklaratë TVSH-je; neni 107, pika 1 dhe 2 — deklarata dorëzohet jo më vonë se 14 ditë pas përfundimit të periudhës tatimore, e cila është muaji kalendarik. Neni 107, pika 5, lejon Ministrin e Financave të caktojë me udhëzim një periudhë tatimore më të gjatë për ndonjë kategori tatimpaguesish; kërkimi për këtë paketim ka gjetur një referencë administrative për një kategori me deklarim tremujor për tatimpagues me qarkullim 2-5 milionë lekë, praktikë e mëparshme e lidhur me pragun e vjetër të regjistrimit (2 milionë lekë) — e pambuluar nga ky pack, siç shënohet në README.md, pasi pragu aktual i regjistrimit (10 milionë lekë, VKM 576/2020) e ka lënë pa objekt shumicën e rasteve të asaj kategorie. Kutitë e mëposhtme janë emërtimet e vetë këtij paketimi, jo numra rreshtash të një formulari me kuti të numëruara: kërkimi i këtij paketimi ka gjetur vetëm kategoritë me emra të Librit të Shitjeve dhe Librit të Blerjeve (burimi «deklarata-tvsh-librat»), të cilat FDP-ja i mbledh; asnjë kopje e drejtpërdrejtë dhe e verifikueshme e ekranit të vetë formularit FDP nuk është gjetur, siç ndodhi edhe me ekranin e e-Beyanname turk (shih packs/tr).', true,'day_of_month_after_period'::filing_deadline_rule, 14, null, 'Ligji Nr. 92/2014, neni 107, pika 1 — deklarata e TVSH-së dorëzohet jo më vonë se 14 ditë pas përfundimit të periudhës tatimore; neni 89 — TVSH-ja e pagueshme paguhet jo më vonë se data e paraqitjes së deklaratës.', 'ligji-92-2014', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

