insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('AL-SKK2-BS', 'AL', 'default', 'Bilanci', 'balance_sheet', 'SKK 2', date '2015-01-01', null, 'Standardi Kombëtar i Kontabilitetit Nr. 2 «Paraqitja e Pasqyrave Financiare», Shtojca 1 «Zërat e bilancit». Ky pack transkripton zërat kryesorë të Shtojcës 1 (kolona «Zëri i bilancit»), duke i paraqitur aktivet afatgjata materiale dhe amortizimin e akumuluar në të njëjtin rresht (vlerë neto) dhe duke kombinuar disa nën-zëra që SKK 2 lejon t''i japë në shënimet shpjeguese në një rresht të vetëm të bilancit; nuk riprodhon zërat e pasqyrave të konsoliduara (aksionet e pakicës, kapitali i shoqërisë mëmë) as ata të veprimeve me instrumente derivativë apo grante, të cilat asnjë llogari e këtij paketimi nuk i kërkon. Shih README.md.', 'skk-2'),
  ('AL-SKK2-IS', 'AL', 'default', 'Pasqyra e të ardhurave dhe shpenzimeve', 'income_statement', 'SKK 2', date '2015-01-01', null, 'Standardi Kombëtar i Kontabilitetit Nr. 2, Shtojca 2, «Formati 1» (pasqyra sipas natyrës së shpenzimit) — SKK 2 lejon zbatimin e vetëm njërit prej dy formateve; ky pack zbaton Formatin 1. Disa zëra të Formatit 1 (fitimet/humbjet nga metoda e kapitalit, pjesa e fitimit për aksionarët e pakicës) i përkasin vetëm pasqyrave të konsoliduara dhe nuk transkriptohen, asnjë llogari e këtij paketimi nuk i kërkon. Shih README.md.', 'skk-2')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

