update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Ligji Nr. 92/2014, neni 99, pika 1, 3 dhe 4 — fatura lëshohet në momentin e furnizimit të mallit ose të kryerjes së shërbimit; neni 98 përjashton nga detyrimi i faturës tatimore me përmbajtje të plotë furnizimet deri në 40 000 lekë, përveç kur blerësi e kërkon. Ligji nuk imponon një format specifik numrash rendorë me vit e numërues; formati këtu është një shembull i pranueshëm dhe jo i vetmi.',
  numbering_source_key          = 'ligji-92-2014',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Ligji Nr. 92/2014, neni 32 — lindja e tatimit ndodh dhe TVSH-ja bëhet e kërkueshme kur furnizimi i mallrave ose shërbimeve kryhet, rregulli i përgjithshëm; neni 33, pika 3 — për çdo pagesë të kryer para furnizimit, TVSH-ja lind në momentin e arkëtimit; pika 4 — kur fatura tatimore lëshohet përpara furnizimit, TVSH-ja bëhet e kërkueshme në momentin e lëshimit të faturës. Furnizimi është rregulli, fatura e lëshuar më parë përjashtimi — e njëjta strukturë si neni 16/17 i ligjit belg dhe neni 21-24, par. 1, i ligjit luksemburgez.',
  tax_point_source_key          = 'ligji-92-2014',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Ligji Nr. 92/2014, neni 95, shkronja «c» — një notë krediti apo notë debiti trajtohet si faturë vetëm nëse ndryshon dhe i referohet në mënyrë specifike e të qartë faturës fillestare, pasi kjo e fundit është lëshuar. Vini re shenjën e kundërt me zakonin: sipas nenit 95(c)(i), «nota e kreditit» RRIT detyrimin e TVSH-së, dhe «nota e debitit» (c)(ii) e ZBRET — e kundërta e emërtimit të zakonshëm anglez apo francez, ku një «credit note»/«note de crédit» zvogëlon shitjen. Dokumenti i korrigjimit të Ekwo (credit_note, që zvogëlon një shitje të postuar) korrespondon pra me «notën e debitit» të nenit 95(c)(ii) të këtij ligji, jo me «notën e kreditit» të tij — shih README.md.',
  posted_edit_policy_source_key = 'ligji-92-2014',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Ligji Nr. 87/2019, datë 18.12.2019, «Për faturën dhe sistemin e monitorimit të qarkullimit» (fiskalizimi) detyron çdo tatimpagues të lëshojë fatura elektronike, të nënshkruara me certifikatë elektronike të lëshuar nga AKSHI, dhe t''i transmetojë në kohë reale në Platformën Qendrore të Faturave të administratës tatimore (CIS), e cila u kthen një Numër Identifikues i Vlefshmërisë së Faturës (NIVF) përpara se fatura t''i konsiderohet e vlefshme — një model *clearance*, jo një shkëmbim i drejtpërdrejtë ndërmjet palëve. Zbatimi u bë me faza, sipas njoftimit të Drejtorisë së Përgjithshme të Tatimeve: transaksionet pa para në dorë ndërmjet tatimpaguesve dhe organeve publike, nga 1 janari 2021; transaksionet pa para në dorë ndërmjet tatimpaguesve, nga 1 korrik 2021; të gjitha transaksionet me para në dorë, pavarësisht xhiros, nga 1 shtator 2021. `mandatory_from` mbetet bosh sepse fusha, sipas skemës së këtij formati, emërton ditën kur bëhet i detyrueshëm profili i EN 16931 që `profile` do të kishte emërtuar — dhe asnjë profil i tillë nuk ekziston këtu; datat e sipërpërmendura mbeten vetëm në këtë `legal_reference`, si te pako `tr` dhe `ro` për mekanizma të ngjashëm *clearance* jo-EN16931. `profile` mbetet bosh: formati i faturës elektronike shqiptare nuk është ndërtuar mbi modelin semantik të EN 16931 (as Peppol BIS, as Factur-X, as XRechnung, as ndonjë PINT) por mbi skemën e vet XML të Drejtorisë së Përgjithshme të Tatimeve, dhe asnjë pjesë e packages/formats/ nuk e shkruan apo transmeton sot këtë skemë — shih seksionin «From Albania» të docs/international.md. `party_scheme` dhe `vat_scheme` mbeten bosh për të njëjtën arsye: një tatimpagues shqiptar identifikohet me NIPT-in e vet (Numri i Identifikimit të Personit të Tatueshëm), jo me një skemë ISO 6523 të regjistruar në rrjetin Peppol.',
  einvoice_source_key           = 'ligji-87-2019',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'AL';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('AL', 'reverse_charge', 'reverse_charge', 'TVSH-ja deklarohet dhe paguhet nga marrësi i shërbimit, sipas pikës 2, të nenit 86, të Ligjit Nr. 92/2014.', '{"en":"VAT is declared and paid by the recipient of the service, under article 86, point 2, of Ligji Nr. 92/2014."}'::jsonb, 10, date '1970-01-01', null, 'Ligji Nr. 92/2014, neni 86, pika 2 — TVSH-ja është e pagueshme nga personi i tatueshëm, të cilit i janë furnizuar shërbimet e përcaktuara në nenin 24, pika 1, nëse furnizuesi nuk është i vendosur në territorin e Republikës së Shqipërisë.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
